blocks = re.findall(r':root(?:\[data-theme="light"\])?\s*\{(.*?)\n\}', css, re.S)[:2]

def declarations(block):
    clean = re.sub(r'/\*.*?\*/', '', block, flags=re.S)
    return dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);', clean))

base, light = map(declarations, blocks)
preview_rules = []
for name in base:
    if name.startswith('--spacing-'):
        preview_rules.append(f'.ds-space-bar[data-token="{name}"] {{ width: var({name}); }}')
    if name.startswith('--radius-'):
        preview_rules.append(f'.ds-radius > div[data-token="{name}"] {{ border-radius: var({name}); }}')
(OUT / 'previews.css').write_text('\n'.join(preview_rules) + '\n')

def group(name):
    if name.startswith('--spacing-'): return 'Spacing'
    if name.startswith('--type-'): return 'Typography'
    if name.startswith(('--radius-', '--avatar-radius-', '--stroke-')): return 'Shape and stroke'
    if name.startswith('--icon-size-'): return 'Icon sizes'
    if name.startswith('--motion-'): return 'Motion'
    if name.startswith(('--layout-', '--size-', '--avatar-size-')): return 'Layout and size'
    if name.startswith(('--color-', '--trend-up-')): return 'Color'
    return 'Component colors'

tokens = [{'name': n, 'default': v.strip(), 'light': light.get(n, v).strip(), 'group': group(n), 'themeOverride': n in light} for n,v in base.items()]
(OUT / 'tokens.json').write_text(json.dumps({'source': '../feed.css', 'updated': '2026-11-05', 'tokens':tokens}, indent=2) + '\n')

